automaFetch('json', {
    url: 'https://openrouter.ai/api/v1/chat/completions',
    method: 'POST',
    headers: {
        "Authorization": automaRefData('variables', 'open_router'),
        "Content-Type": "application/json"
    },
    body: JSON.stringify({
        "model": "google/gemini-3.1-flash-image-preview",
        "messages": [
            {
                "role": "user",
                "content": [
                    {
                        "type": "text",
                        "text": automaRefData('variables', 'image_prompt')
                    }
                ]
            }
        ],
        "modalities": ["image", "text"]
    })
}).then(response => {
    const message = response?.choices?.[0]?.message;

    if (!message) {
        throw new Error("Invalid response from API");
    }

    // OpenRouter returns generated images inside message.images (array of {image_url:{url}})
    // url is usually a base64 data URI: "data:image/png;base64,...."
    const imageUrl = message.images?.[0]?.image_url?.url;

    if (!imageUrl) {
        throw new Error("No image returned: " + JSON.stringify(message));
    }

    automaSetVariable('generated_image', imageUrl);
    automaNextBlock();
    console.log(imageUrl);
})
.catch(err => {
    console.error(err);
    automaSetVariable('generated_image', "");
    automaNextBlock();
});

