automaFetch('json', {
    url: 'https://openrouter.ai/api/v1/chat/completions',
    method: 'POST',
    headers: {
        "Authorization": automaRefData('variables', 'open_router'),
        "Content-Type": "application/json"
    },
    body: JSON.stringify({
        "model": "openai/gpt-4o-mini",
        "messages": [
            {
                "role": "user",
                "content": [
                    {
                        "type": "text",
                        "text": `Analyze this picture and write Facebook post metadata for it, as if you're a musician promoting your beat.
                        return ONLY valid JSON, no markdown, no code fences, in this exact shape:
                        {
                          "caption": "string",
                          "hashtags": ["tag1", "tag2", "..."]
                        }
                        caption rules:
                        • lowercase letters only.
                        • no emojis.
                        • 2-4 sentences, casual and relaxed, like a real conversation with the client.
                        • soft marketing tone, not pushy or dramatic.
                        • consider the post's existing caption/context if provided as part of context.
                        • sometimes (not always, not forced) mention: music producer warhol.voo, real name ustym haramtiuk, making music since 2010, producing rap beats since 2020.
                        hashtags rules:
                        • 5-10 relevant hashtags.
                        • lowercase, no spaces, mix of niche (rap beats, hip hop producer) and broad (music, producer) tags.
                        • no duplicate or near-duplicate tags.
                        `
                    },
                    {
                        "type": "image_url",
                        "image_url": {
                            "url": automaRefData('variables', 'generated_image')
                        }
                    }
                ]
            }
        ]
    })
}).then(response => {
    if (!response?.choices?.[0]?.message?.content) {
        throw new Error("Invalid response from API");
    }

    let raw = response.choices[0].message.content.trim();
    raw = raw.replace(/^```json\s*|```$/g, "").trim();

    let parsed;
    try {
        parsed = JSON.parse(raw);
    } catch (e) {
        throw new Error("Failed to parse metadata JSON: " + raw);
    }

    automaSetVariable('fb_caption', parsed.caption || "");
    automaSetVariable('fb_hashtags', "#" + (parsed.hashtags || []).join(" #"));
    automaNextBlock();
    console.log(parsed);
})
.catch(err => {
    console.error(err);
    automaSetVariable('fb_caption', "");
    automaSetVariable('fb_hashtags', "");
    automaNextBlock();
});
